<template><section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">ANALYTICS</p><h1>Reports</h1><p class="page-subtitle">รายงานการดำเนินงานของคลินิก</p></div></header><div class="profile-card report-filter"><label>ตั้งแต่<input v-model="from" type="date"></label><label>ถึง<input v-model="to" type="date"></label><button @click="load">โหลดรายงาน</button></div><p v-if="errorMessage" class="error">{{ errorMessage }}</p><div v-if="loading" class="state-card">กำลังโหลดรายงาน...</div><div v-else class="patient-results"><article v-for="item in cards" :key="item.label" class="patient-result-card"><div><span class="patient-hn">{{ item.label }}</span><h2>{{ item.value }}</h2><p>{{ item.detail }}</p></div></article></div><details v-if="raw"><summary>ข้อมูลดิบสำหรับตรวจสอบ</summary><pre>{{ JSON.stringify(raw, null, 2) }}</pre></details></section></template>
<script setup lang="ts">import { computed, ref } from 'vue'; import { loadReport } from '@/api/reports-full'; const today=new Date().toISOString().slice(0,10); const from=ref(today.slice(0,8)+'01'); const to=ref(today); const loading=ref(false); const errorMessage=ref(''); const raw=ref<Record<string,unknown>|null>(null); const cards=computed(()=>{const x=raw.value??{}; return Object.entries(x).filter(([_,v])=>typeof v==='number'||typeof v==='string').slice(0,8).map(([label,value])=>({label,value:String(value),detail:'จากข้อมูลตามช่วงวันที่เลือก'}))}); async function load(){loading.value=true;errorMessage.value='';try{raw.value=await loadReport('revenue',from.value,to.value)}catch(e){errorMessage.value=e instanceof Error?e.message:'เกิดข้อผิดพลาด'}finally{loading.value=false}} load()</script>
